/// `MilestoneInputForm` filled from a `Milestone` as the API sends it: each
/// field the two share by name and kind; any other as a new form has it.
fn fill_milestone_input_form_from_milestone(json: &Value) -> MilestoneInputForm {
    let mut form = MilestoneInputForm::new();
    form.title = held(&json["title"]);
    form.due_on = held(&json["dueOn"]);
    form
}

/// `ProjectPatchForm` filled from a `Project` as the API sends it: each field
/// the two share by name and kind; any other as a new form has it.
fn fill_project_patch_form_from_project(json: &Value) -> ProjectPatchForm {
    let mut form = ProjectPatchForm::new();
    form.name = held(&json["name"]);
    form.owner_id = held(&json["ownerId"]);
    form.status = held(&json["status"]);
    form.budget = held(&json["budget"]);
    form.description = held(&json["description"]);
    form.due_on = held(&json["dueOn"]);
    if let Some(rows) = json["tags"].as_array() {
        form.tags = rows.iter().map(held).collect();
    }
    if let Some(rows) = json["milestones"].as_array() {
        form.milestones = rows.iter().map(fill_milestone_input_form_from_milestone).collect();
    }
    form
}

