async fn projects_tasks_section(cx: &Cx, project_id: String) -> topcoat::Result<impl View> {
    let listed = match operations::can_task_list_tasks(cx).await {
        Ok(_) => Some(call_task_list_tasks(cx, &project_id).await),
        Err(_) => None,
    };
    let creates = operations::can_task_add_task(cx).await.is_ok();
    let href = projects_tasks_href(&project_id).unwrap_or_default();
    Ok(view! {
        if listed.is_some() || creates {
            <section class="ss-section" data-resource="tasks">
                <h2><a href=(href.clone())>"Tasks"</a></h2>
                if creates {
                    <p class="ss-actions"><a class="ss-new" href=(format!("{href}/new"))>"New task"</a></p>
                }
                match listed {
                    Some(Ok(items)) => projects_tasks_rows(project_id: project_id, items: items),
                    Some(Err(refusal)) => <p class="ss-refused">(messages(&refusal).join(" "))</p>,
                    None => "",
                }
            </section>
        }
    })
}

